import pathlib, json, shutil, datetime, re, subprocess, os
payload = json.loads('{"ingest": "export const ingestRecordingHandler = async (req: Request, res: Response): Promise<void> => {\\n  try {\\n    const authHeader = req.headers.authorization;\\n    const providedKey = authHeader?.startsWith(\'Bearer \') ? authHeader.slice(7) : undefined;\\n    if (!process.env.RECORDING_INGEST_KEY || providedKey !== process.env.RECORDING_INGEST_KEY) {\\n      res.status(401).json({ error: \'Invalid or missing ingest key\' });\\n      return;\\n    }\\n\\n    const { roomSlug, fileUrl, status = \'Ready\', recordedAt } = req.body;\\n    const relativeFile = req.body.relativeFile || fileUrl;\\n    const recordingSessionId = req.body.recordingSessionId || (typeof relativeFile === \'string\' ? relativeFile.split(\'/\')[0] : undefined);\\n    if (typeof recordingSessionId !== \'string\' || !/^[a-zA-Z0-9_-]{8,128}$/.test(recordingSessionId) || ![\'Processing\', \'Ready\', \'Failed\'].includes(status)) {\\n      res.status(400).json({ error: \'Valid recordingSessionId and status are required\' }); return;\\n    }\\n    if (!roomSlug || typeof roomSlug !== \'string\') {\\n      res.status(400).json({ error: \'roomSlug is required\' });\\n      return;\\n    }\\n    if (status === \'Ready\' && (typeof fileUrl !== \'string\' || typeof relativeFile !== \'string\')) {\\n      res.status(400).json({ error: \'Completed recording requires a fileUrl and relativeFile in the recording mount\' }); return;\\n    }\\n\\n    const meeting = await Meeting.findOne({ roomSlug: roomSlug.trim().toLowerCase() });\\n    if (!meeting) {\\n      res.status(404).json({ error: `No meeting found with roomSlug \\"${roomSlug}\\"` });\\n      return;\\n    }\\n\\n    if (meeting.companyId) {\\n      const company = await Company.findById(meeting.companyId).select(\'meetingPolicy limits status\');\\n      if (!company || company.status !== \'ACTIVE\' || company.meetingPolicy?.recordingEnabled === false || company.limits?.featureFlags?.recordingEnabled === false) {\\n        res.status(403).json({ error: \'Recording is disabled by company policy for this organization\' });\\n        return;\\n      }\\n    }\\n\\n    let recording = await Recording.findOne({ recordingSessionId });\\n    if (recording && String(recording.meetingId) !== String(meeting._id)) { res.status(409).json({ error: \'Recording session belongs to another meeting\' }); return; }\\n    if (recording?.status === \'Ready\') { res.json({ recording }); return; }\\n    if (!recording) {\\n      try {\\n        recording = await Recording.create({ recordingSessionId, companyId: meeting.companyId || null,\\n          meetingId: meeting._id, createdBy: meeting.createdBy, name: meeting.name,\\n          recordedAt: recordedAt ? new Date(recordedAt) : new Date(), durationMinutes: 0, sizeBytes: 0, status: \'Processing\' });\\n      } catch (error: any) {\\n        if (error.code === 11000) { res.status(409).json({ error: \'Recording finalization is already in progress; retry this session ID\' }); return; }\\n        throw error;\\n      }\\n    }\\n    if (status === \'Processing\') { res.status(202).json({ recording }); return; }\\n    if (status === \'Failed\') {\\n      await Recording.updateOne({ _id: recording._id, status: { $ne: \'Ready\' } }, { $set: { status: \'Failed\', failureReason: \'Recorder reported failure\' } });\\n      res.json({ recording: await Recording.findById(recording._id) }); return;\\n    }\\n    try {\\n      const metadata = await inspectRecording(relativeFile);\\n      // CAS prevents late processing/failure retries from overwriting a finalized result.\\n      const ready = await Recording.findOneAndUpdate({ _id: recording._id, status: { $ne: \'Ready\' } }, { $set: {\\n        durationSeconds: metadata.durationSeconds, durationMinutes: metadata.durationSeconds / 60,\\n        sizeBytes: metadata.sizeBytes, status: \'Ready\', fileUrl, allowDownload: true,\\n      }, $unset: { failureReason: 1 } }, { new: true });\\n      if (!ready) { res.json({ recording: await Recording.findById(recording._id) }); return; }\\n      recording = ready;\\n    } catch {\\n      await Recording.updateOne({ _id: recording._id, status: { $ne: \'Ready\' } }, { $set: {\\n        status: \'Failed\', failureReason: \'Media validation failed; check recorder finalization, recording mount and ffprobe/ffmpeg logs\', allowDownload: false,\\n      }, $unset: { fileUrl: 1 } });\\n      res.status(422).json({ error: \'Recording failed media validation\', recordingSessionId }); return;\\n    }\\n\\n    const notifyPayload = {\\n      category: \'RECORDINGS\' as const,\\n      type: \'RECORDING_READY\' as const,\\n      title: \'Recording is ready\',\\n      description: `The recording for \\"${meeting.name}\\" is ready to view.`,\\n      relatedName: meeting.name,\\n      actionLabel: \'View\' as const,\\n      actionUrl: `/dashboard?tab=recordings`,\\n    };\\n    if (meeting.companyId) {\\n      notifyCompany(meeting.companyId, notifyPayload);\\n    } else {\\n      notifyUser({ userId: meeting.createdBy, ...notifyPayload });\\n    }\\n\\n    res.status(201).json({ recording });\\n  } catch (error: any) {\\n    console.error(\'[Recordings] Error ingesting recording:\', error.message);\\n    res.status(500).json({ error: \'Failed to ingest recording\' });\\n  }\\n};\\n\\n", "media": "import { promises as fs } from \'fs\';\\nimport path from \'path\';\\nimport { execFile } from \'child_process\';\\nimport { promisify } from \'util\';\\nconst execute = promisify(execFile);\\n\\nexport function parseProbe(probe: any, sizeBytes: number) {\\n  const durationSeconds = Number(probe.format?.duration);\\n  const streams = probe.streams || [];\\n  if (!Number.isFinite(durationSeconds) || durationSeconds <= 0 || !Number.isSafeInteger(sizeBytes) || sizeBytes <= 0\\n    || !streams.some((s: any) => s.codec_type === \'video\') || !streams.some((s: any) => s.codec_type === \'audio\')) {\\n    throw new Error(\'Completed recording must contain video, audio and a positive duration\');\\n  }\\n  return { durationSeconds, sizeBytes, container: String(probe.format?.format_name || \'\'),\\n    codecs: streams.map((s: any) => String(s.codec_name || \'unknown\')) };\\n}\\n\\n/** Probe only a completed local file in the configured recorder mount. Never fetch caller URLs. */\\nexport async function inspectRecording(relativeFile: string) {\\n  const root = await fs.realpath(process.env.RECORDING_ROOT || process.env.RECORDINGS_STORAGE_PATH || \'/recordings-storage\');\\n  const file = await fs.realpath(path.resolve(root, relativeFile));\\n  const relative = path.relative(root, file);\\n  if (!relative || relative.startsWith(\'..\') || path.isAbsolute(relative)) throw new Error(\'Recording path is outside the recording root\');\\n  const before = await fs.stat(file);\\n  if (!before.isFile()) throw new Error(\'Recording is not a regular file\');\\n  const { stdout } = await execute(process.env.FFPROBE_PATH || \'ffprobe\', [\'-v\', \'error\', \'-show_format\', \'-show_streams\', \'-of\', \'json\', file],\\n    { timeout: 30000, maxBuffer: 1024 * 1024, windowsHide: true });\\n  const metadata = parseProbe(JSON.parse(stdout), before.size);\\n  // A valid container header alone cannot rule out truncated or undecodable content.\\n  await execute(process.env.FFMPEG_PATH || \'ffmpeg\', [\'-v\', \'error\', \'-xerror\', \'-i\', file, \'-map\', \'0:v:0\', \'-map\', \'0:a:0\', \'-f\', \'null\', \'-\'],\\n    { timeout: 10 * 60 * 1000, maxBuffer: 1024 * 1024, windowsHide: true });\\n  const after = await fs.stat(file);\\n  if (before.size !== after.size || before.mtimeMs !== after.mtimeMs) throw new Error(\'Recording is still being written\');\\n  return metadata;\\n}\\n", "finalizer": "#!/usr/bin/env python3\\n\\"\\"\\"Jibri finalize hook. Validate completed media, then retry idempotent ingestion.\\"\\"\\"\\nimport json, os, pathlib, subprocess, sys, time, urllib.request\\nroot = pathlib.Path(os.environ.get(\'JIBRI_RECORDING_ROOT\', \'/storage/recordings\')).resolve()\\nfolder = pathlib.Path(sys.argv[1]).resolve()\\nif not folder.is_relative_to(root) or folder == root:\\n    raise SystemExit(\'Invalid recording directory\')\\nfiles = list(folder.glob(\'*.mp4\'))\\nif len(files) != 1:\\n    raise SystemExit(\'Expected exactly one completed MP4\')\\nmedia = files[0].resolve()\\nif not media.is_relative_to(root):\\n    raise SystemExit(\'Invalid recording path\')\\nkey = os.environ.get(\'RECORDING_INGEST_KEY\') or pathlib.Path(\'/config/recording-ingest.key\').read_text().strip()\\nurl = os.environ.get(\'RECORDING_BACKEND_URL\', \'http://toowix-backend:4000\') + \'/api/recordings/ingest\'\\nroom = media.stem.rsplit(\'_\', 1)[0]\\npayload = dict(roomSlug=room, recordingSessionId=folder.name, relativeFile=str(media.relative_to(root)), fileUrl=str(media.relative_to(root)))\\ndef post(status, **metadata):\\n    body = json.dumps(dict(payload, status=status, **metadata)).encode()\\n    for attempt in range(4):\\n        try:\\n            request = urllib.request.Request(url, data=body, headers={\'Content-Type\':\'application/json\', \'Authorization\':\'Bearer \'+key})\\n            with urllib.request.urlopen(request, timeout=660) as response:\\n                response.read()\\n            print(time.strftime(\'%Y-%m-%dT%H:%M:%SZ\', time.gmtime()), folder.name, status, flush=True)\\n            return\\n        except Exception:\\n            if attempt == 3: raise RuntimeError(\'Recording ingestion failed after retries\') from None\\n            time.sleep(2 ** attempt)\\npost(\'Processing\')\\ntry:\\n    before = media.stat()\\n    probe = json.loads(subprocess.check_output([\'ffprobe\',\'-v\',\'error\',\'-show_format\',\'-show_streams\',\'-of\',\'json\',str(media)], timeout=30))\\n    duration = float(probe[\'format\'][\'duration\'])\\n    kinds = {stream[\'codec_type\'] for stream in probe[\'streams\']}\\n    if duration <= 0 or before.st_size <= 0 or not {\'audio\',\'video\'} <= kinds:\\n        raise ValueError(\'Missing audio/video or duration\')\\n    subprocess.run([\'ffmpeg\',\'-v\',\'error\',\'-xerror\',\'-i\',str(media),\'-map\',\'0:v:0\',\'-map\',\'0:a:0\',\'-f\',\'null\',\'-\'], check=True, timeout=600, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\\n    after = media.stat()\\n    if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):\\n        raise ValueError(\'File still changing\')\\nexcept Exception:\\n    post(\'Failed\')\\n    raise SystemExit(\'Recording media validation failed\')\\npost(\'Ready\', durationSeconds=duration, durationMinutes=duration/60, sizeBytes=after.st_size)\\n"}')
